from collections import OrderedDict

class TTLCache:
    """Mapping with per-entry expiry.

    `clock` is a zero-argument callable returning a monotonic float, injected so
    tests can control time.
    """

    def __init__(self, ttl, clock, max_ size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_size = max_ size
        self._data = OrderedDict()

    def set(self, key, value):
        if self.max_size == 0:
            return
        if key in self._data:
            # Move to end (most recent) and update timestamp.
            self._data.move_to_end(key)
            # Replace the tuple with new timestamp.
            old_val, _ = self._data[key]
            self._data[key] = (value, self.clock())
        else:
            if self.max_size is not None and self.max_size > 0 and len(self._data) >= self.max_size:
                # Evict least recently used entry.
                self._data.popitem(last=False)
            self._data[key] = (value, self.clock())

    def get(self, key, default=None):
        if self.max_size == 0:
            return default
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
        # Key is present and not expired; mark as recently used.
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

