class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns  (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    @staticmethod
    def _is_static(pattern):
        return '<' not in pattern

    def resolve(self, path):
        # Check static routes (no parameters) for exact match first.
        for pattern, handler in self._routes:
            if self._is_static(pattern) and pattern == path:
                return handler, {}
        # Then try dynamic routes in registration order.
        path_segments = [s for s in path.split('/') if s]
        for pattern, handler in self._routes:
            if not self._is_static(pattern):
                route_segments = [s for s in pattern.split('/') if s]
                if len(route_segments) != len(path_segments):
                    continue
                params = {}
                match = True
                for seg_pat, seg_path in zip(route_segments, path_segments):
                    if '<' in seg_pat and seg_pat.endswith('>'):
                        name = seg_pat[1:-1]
                        # Ensure the captured value is non‑empty (segment already non‑empty)
                        params[name] = seg_path
                    else:
                        if seg_pat != seg_path:
                            match = False
                            break
                if match:
                    return handler, params
        return None, {}

