import heapq
import itertools


class JobQueue:
    """A priority queue of jobs."""

    def __init__(self):
        self._heap = []
        # itertools.count provides an ever-increasing unique tie-breaker.
        self._counter = itertools.count()

    def push(self, job, priority=5):
        # Push a tuple (priority, insertion_order, job) so that equal priorities
        # are ordered by the order of insertion.
        heapq.heappush(self._heap, (priority, next(self._counter), job))

    def pop(self):
        if not self._heap:
            return None
        _, _, job = heapq.heappop(self._heap)
        return job

    def __len__(self):
        return len(self._heap)

