from collections import OrderedDict

class TTLCache:
    """Mapping with per-entry expiry.

    `clock` is a zero-argument callable returning a monotonic float, injected so
    tests can control time.
    """

    def __init__(self, ttl, clock, max_Size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_Size = max_Size  # None means unlimited size
        self._data = OrderedDict()

    def set(self, key, value):
        if self.max_Size == 0:
            return
        stamp = self.clock()
        if key in self._data:
            # update existing entry and mark as recently used
            val, _ = self._data[key]
            self._data.move_to_end(key)
            self._data[key] = (value, stamp)
        else:
            if self.max_Size is not None and len(self._data) >= self.max_Size:
                # evict least recently used entry
                self._data.popitem(last=False)
            self._data[key] = (value, stamp)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        now = self.clock()
        if now - stamp >= self.ttl:
            del self._data[key]
            return default
        # mark as recently used
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

